// Map user identity to Kubernetes RBAC groups
const input = items[0].json;
const userId = input.userId || input.owner || 'developer@company.com';
const username = userId.split('@')[0];

return [{
  json: {
    userId,
    groups: ['devaiportal-developers', `team-${username}`],
    displayName: username
  }
}];
